namespace DataMaker.Refactored.Services;
public sealed record RunResult(bool Success,string Output,string Error,TimeSpan Duration);
public sealed class RunnerService
{ public async Task<RunResult> RunAsync(string executable,string input,int timeoutMs,int memoryLimitMb=0,int maxOutputMb=64,CancellationToken token=default){var start=DateTime.UtcNow;var psi=new System.Diagnostics.ProcessStartInfo(executable){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};using var p=System.Diagnostics.Process.Start(psi)??throw new InvalidOperationException("无法启动标程");using var job=JobObjectService.TryCreate(memoryLimitMb);if(job is not null&&!job.TryAssign(p)){job.Dispose();}await p.StandardInput.WriteAsync(input);p.StandardInput.Close();var outputTask=p.StandardOutput.ReadToEndAsync(token);var errorTask=p.StandardError.ReadToEndAsync(token);using var timeout=CancellationTokenSource.CreateLinkedTokenSource(token);timeout.CancelAfter(timeoutMs);try{await p.WaitForExitAsync(timeout.Token);}catch(OperationCanceledException){try{job?.Kill();p.Kill(true);}catch{}return new(false,"",token.IsCancellationRequested?"已中止":"运行超时",DateTime.UtcNow-start);}var output=await outputTask;var error=await errorTask;if(maxOutputMb>0&&output.Length>maxOutputMb*1024L*1024L){try{p.Kill(true);}catch{}return new(false,"","标程输出超过限制",DateTime.UtcNow-start);}if(p.ExitCode!=0)return new(false,output,$"退出码：{p.ExitCode}\n{error}",DateTime.UtcNow-start);if(string.IsNullOrWhiteSpace(output))return new(false,output,"标程输出为空",DateTime.UtcNow-start);return new(true,output,error,DateTime.UtcNow-start);}}
